package com.srent.payment;
import com.srent.booking.Booking; import com.srent.common.BaseEntity; import com.srent.user.User; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal;
@Entity @Table(name="payments") @Getter @Setter @NoArgsConstructor
public class Payment extends BaseEntity { public enum Status{PENDING,HELD,RELEASED,REFUNDED,FAILED} @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="booking_id",nullable=false) private Booking booking; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="student_id",nullable=false) private User student; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="landlord_id",nullable=false) private User landlord; @Column(nullable=false) private BigDecimal amount; @Column(nullable=false) private String currency="VND"; @Enumerated(EnumType.STRING) @Column(nullable=false) private Status status=Status.PENDING; @Column(nullable=false) private String provider="MOCK"; @Column(name="provider_reference",nullable=false,unique=true) private String providerReference; @Version private long version; }
